class UserAccessTemporalCodeRegisterCodeExpirationAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getRegisterCodeExpiration returns null on a freshly created holder.
         */
        public function testRegisterCodeExpirationNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserAccessTemporalCodeRegisterCodeExpirationAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isRegisterCodeExpirationAssigned());
            $this->assertNull($holder->getRegisterCodeExpiration());
        }
